'use strict';
// Public quotations remain distinct from the fictional meme copy.
function renderRealQuotes(){const list=$('#real-quote-list');list.replaceChildren();realQuotes.forEach(q=>{const article=document.createElement('article');article.className='real-quote';const tag=document.createElement('span');tag.className='quote-type';tag.textContent='孙哥原话';const quote=document.createElement('blockquote');quote.textContent='“'+q.text+'”';const context=document.createElement('p');context.textContent=q.context;const link=document.createElement('a');link.className='source-link';link.href=q.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=q.source+' ↗';article.append(tag,quote,context,link);list.append(article)})}
$('#open-originals').addEventListener('click',()=>{renderRealQuotes();openDialog($('#originals'))});

const drinkKey='water-theory-drinking-v1', quizKey='water-theory-quiz-v1';
let waterData={goal:null,entries:[]};
try{const saved=JSON.parse(localStorage.getItem(drinkKey)||'null');if(saved&&typeof saved==='object'){waterData.goal=Number.isInteger(saved.goal)&&saved.goal>0&&saved.goal<=10000?saved.goal:null;if(Array.isArray(saved.entries))waterData.entries=saved.entries.filter(e=>e&&typeof e.id==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(e.day)&&Number.isInteger(e.amount)&&e.amount>0&&e.amount<=5000&&Number.isFinite(e.at))}}catch{}
function beijingDay(date=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const find=t=>parts.find(p=>p.type===t).value;return `${find('year')}-${find('month')}-${find('day')}`}
function dayBefore(day,offset){const d=new Date(day+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()-offset);return beijingDay(d)}
function dailyEntries(day){return waterData.entries.filter(e=>e.day===day)}
function dailyTotal(day){return dailyEntries(day).reduce((n,e)=>n+e.amount,0)}
let currentDay=beijingDay();$('#drink-date').value=currentDay;$('#drink-date').max=currentDay;
function drinkMessage(message){$('#drink-feedback').textContent=message}
function saveDrinks(){try{localStorage.setItem(drinkKey,JSON.stringify(waterData));return true}catch{drinkMessage('本次已记在当前页面，但浏览器未允许保存；刷新后可能丢失。');return false}}
function renderDrinks(){const day=$('#drink-date').value||beijingDay(),total=dailyTotal(day),entries=dailyEntries(day),goal=waterData.goal;$('#today-water').textContent=dailyTotal(beijingDay())+' mL';$('#drink-total').innerHTML=total+' <small>mL</small>';$('#drink-progress').textContent=goal?`自定目标 ${goal} mL · 已记录 ${Math.round(total/goal*100)}%`:(total?`已记录 ${entries.length} 笔，吨吨吨。`:'还没记录，喝完再来。');$('#drink-meter-fill').style.width=goal?Math.min(100,total/goal*100)+'%':'0%';$('.drink-meter').hidden=!goal;$('#undo-water').disabled=!entries.length;const log=$('#water-log');log.replaceChildren();if(!entries.length){const empty=document.createElement('li');empty.className='empty-note';empty.textContent='今天的瓶子还是空的。';log.append(empty)}else entries.slice().reverse().forEach(e=>{const li=document.createElement('li');const time=document.createElement('time');time.dateTime=new Date(e.at).toISOString();time.textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(e.at));const amount=document.createElement('strong');amount.textContent=`＋${e.amount} mL`;const del=document.createElement('button');del.type='button';del.className='delete-entry';del.textContent='删除';del.setAttribute('aria-label',`删除 ${time.textContent} 的 ${e.amount} mL 记录`);del.addEventListener('click',()=>{waterData.entries=waterData.entries.filter(x=>x.id!==e.id);drinkMessage('这笔已删除。');saveDrinks();renderDrinks()});li.append(time,amount,del);log.append(li)});const week=$('#week-water');week.replaceChildren();const days=Array.from({length:7},(_,i)=>dayBefore(beijingDay(),6-i));const max=Math.max(1,...days.map(dailyTotal));days.forEach(d=>{const amount=dailyTotal(d);const bar=document.createElement('div');bar.className='week-day';bar.setAttribute('aria-label',`${d}：${amount} mL`);const n=document.createElement('span');n.textContent=amount;const track=document.createElement('div');track.className='week-track';const fill=document.createElement('i');fill.style.height=Math.max(2,amount/max*100)+'%';track.append(fill);const label=document.createElement('small');label.textContent=d.slice(5).replace('-','/');bar.append(n,track,label);week.append(bar)})}
function recordWater(amount){const day=$('#drink-date').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||day>beijingDay()){drinkMessage('请选择今天或以前的日期。');return}if(!Number.isInteger(amount)||amount<1||amount>5000){drinkMessage('请输入 1–5000 之间的整数 mL，记录实际喝水量。');return}waterData.entries.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10),day,amount,at:Date.now()});drinkMessage(`已记录 ${amount} mL。`);saveDrinks();renderDrinks()}
function refreshDay(){const next=beijingDay();if(next!==currentDay){if($('#drink-date').value===currentDay)$('#drink-date').value=next;currentDay=next;$('#drink-date').max=next;renderDrinks()}}
$('#open-drinking').addEventListener('click',()=>{refreshDay();$('#drink-date').value=beijingDay();$('#water-goal').value=waterData.goal||'';drinkMessage('');renderDrinks();openDialog($('#drinking'))});$('#drink-date').addEventListener('change',()=>{drinkMessage('');renderDrinks()});document.querySelectorAll('[data-water]').forEach(b=>b.addEventListener('click',()=>recordWater(Number(b.dataset.water))));$('#custom-water').addEventListener('submit',e=>{e.preventDefault();const raw=$('#water-amount').value;if(!raw.trim())return;recordWater(Number(raw));$('#water-amount').value=''});$('#goal-form').addEventListener('submit',e=>{e.preventDefault();const raw=$('#water-goal').value.trim(),goal=raw===''?null:Number(raw);if(goal!==null&&(!Number.isInteger(goal)||goal<1||goal>10000)){drinkMessage('目标请输入正整数，或留空取消。');return}waterData.goal=goal;drinkMessage(goal?'自己的目标已保存。':'已取消每日目标。');saveDrinks();renderDrinks()});$('#undo-water').addEventListener('click',()=>{const entries=dailyEntries($('#drink-date').value),last=entries.at(-1);if(!last)return;waterData.entries=waterData.entries.filter(e=>e.id!==last.id);drinkMessage(`已撤销 ${last.amount} mL。`);saveDrinks();renderDrinks()});window.addEventListener('focus',refreshDay);setInterval(refreshDay,30000);window.addEventListener('storage',e=>{if(e.key===drinkKey){try{const s=JSON.parse(e.newValue);if(s&&Array.isArray(s.entries)){waterData.goal=Number.isInteger(s.goal)&&s.goal>0&&s.goal<=10000?s.goal:null;waterData.entries=s.entries.filter(x=>x&&typeof x.id==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.day)&&Number.isInteger(x.amount)&&x.amount>0&&x.amount<=5000&&Number.isFinite(x.at));renderDrinks()}}catch{}}});renderDrinks();

const questions=[
 {question:'出门前，突然想买一杯包装很漂亮的饮料。你会？',dimension:0,options:[['喜欢就买，开心也是价值。',0],['先看看价格，偶尔犒劳一下。',1],['自带水壶，把钱留给更在意的事。',2]]},
 {question:'想学一项新技能，你的开场动作是？',dimension:1,options:[['先收藏 20 个教程，改天再说。',0],['挑个课程，安排这周开始。',1],['今天先练 15 分钟，再决定下一步。',2]]},
 {question:'全网都在夸一个新机会，你会？',dimension:2,options:[['这么多人说好，赶紧跟上。',0],['先问问朋友怎么想。',1],['查原始信息，也找反对理由再判断。',2]]},
 {question:'一件东西有实用款和贵三倍的“排面款”。你怎么选？',dimension:0,options:[['排面很重要，买贵的。',0],['预算允许就选喜欢的，不允许就实用。',1],['先看自己的需求，够用就好。',2]]},
 {question:'计划一周后没什么进展，你会？',dimension:1,options:[['等状态好了，再全力开始。',0],['重新做份更详细的计划。',1],['缩小动作，今天做一点并记录。',2]]},
 {question:'有人嘲笑你提着大水壶，你会？',dimension:2,options:[['马上换个看起来更高级的。',0],['有点尴尬，解释一下。',1],['不急着证明，自己觉得好用就行。',2]]}
];
let quizIndex=0,answers=Array(questions.length).fill(null),lastResult=null;
try{const s=JSON.parse(localStorage.getItem(quizKey)||'null');if(s&&Array.isArray(s.answers)&&s.answers.length===questions.length&&s.answers.every(x=>Number.isInteger(x)&&x>=0&&x<3))lastResult=s}catch{}
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
function getQuizResult(values){const dimensions=[0,0,0];questions.forEach((q,i)=>dimensions[q.dimension]+=q.options[values[i]][1]);const score=Math.round(dimensions.reduce((a,b)=>a+b,0)/12*100);const level=score>=75?'大水思维选手':score>=50?'大水实践派':score>=25?'微澜观察员':'随缘小水派';const line=score>=75?'水壶在手，做事不等风来。':score>=50?'已经摸到瓶盖，再拧一圈。':score>=25?'先观察水势，也是一种风格。':'快乐优先，别忘了自己的节奏。';return {dimensions,score,level,line}}
function renderQuiz(){const root=$('#quiz-content');root.replaceChildren();const q=questions[quizIndex];const progress=node('div',`${quizIndex+1} / ${questions.length}`,'quiz-progress');const track=node('div',undefined,'quiz-track');const fill=node('i');fill.style.width=quizIndex/questions.length*100+'%';track.append(fill);const form=node('form');form.id='quiz-form';const fs=node('fieldset');const legend=node('legend',q.question);fs.append(legend);q.options.forEach(([text],i)=>{const label=node('label',undefined,'quiz-option');const input=node('input');input.type='radio';input.name='answer';input.value=i;input.checked=answers[quizIndex]===i;input.required=true;input.addEventListener('change',()=>{answers[quizIndex]=i;form.querySelector('button[type="submit"]').disabled=false});label.append(input,node('span',String.fromCharCode(65+i),'option-letter'),node('span',text));fs.append(label)});const actions=node('div',undefined,'quiz-actions');const prev=node('button','上一题','secondary-button');prev.type='button';prev.disabled=quizIndex===0;prev.addEventListener('click',()=>{quizIndex--;renderQuiz()});const next=node('button',quizIndex===questions.length-1?'看看我的大水思维 ↗':'下一题 ↗','primary-button');next.type='submit';next.disabled=answers[quizIndex]===null;actions.append(prev,next);form.append(fs,actions);form.addEventListener('submit',e=>{e.preventDefault();if(answers[quizIndex]===null)return;if(quizIndex<questions.length-1){quizIndex++;renderQuiz()}else{lastResult={answers:answers.slice(),at:Date.now()};try{localStorage.setItem(quizKey,JSON.stringify(lastResult))}catch{}renderQuizResult(lastResult.answers)}});root.append(progress,track,form);}
function renderQuizResult(values){const root=$('#quiz-content');root.replaceChildren();const result=getQuizResult(values);root.append(node('p','你的大水思维含量','result-label'),node('div',result.score+'%','quiz-score'),node('h3',result.level,'quiz-persona'),node('p',result.line,'result-line'));const details=node('div',undefined,'dimension-list');['消费取舍','小步执行','独立判断'].forEach((name,i)=>{const row=node('div');row.append(node('span',name),node('strong',result.dimensions[i]+' / 4'));details.append(row)});root.append(details,node('p','分数按本站题目选项计算，只供娱乐；不判断人格、财富或健康。','local-note'));const actions=node('div',undefined,'quiz-actions');const restart=node('button','再测一次','secondary-button');restart.addEventListener('click',()=>{answers=Array(questions.length).fill(null);quizIndex=0;renderQuiz()});const copy=node('button','复制我的结果','primary-button');copy.addEventListener('click',async()=>{const text=`我的大水思维含量 ${result.score}% · ${result.level}。${result.line}（大水理论原创娱乐测试）`;try{await navigator.clipboard.writeText(text);copy.textContent='已复制 ✓'}catch{const existing=root.querySelector('textarea');if(existing)existing.remove();const field=node('textarea');field.value=text;field.readOnly=true;field.setAttribute('aria-label','测试结果，可手动复制');root.append(field);field.focus();field.select();copy.textContent='请手动复制下方文字'}});actions.append(restart,copy);root.append(actions)}
$('#open-quiz').addEventListener('click',()=>{if(lastResult)renderQuizResult(lastResult.answers);else renderQuiz();openDialog($('#quiz'))});
